response:
**Gates before launch**

I run six gates before I launch. First, `git status -- spe/` must be clean, and `git log` must show the commit that added spe/predictions/r04.yaml and spe/plans/r04.md. That proves the predictions were on record before any round 4 data existed. Second, I check the script constants against spe/plans/r04.md one by one. The plan says configs B and C2, 50 tickets, 5 trials, grade.py with answers.json, judge.md on Opus, and a $40 cap. Third, I run grade.py on round 3's saved outputs. It must reproduce round 3's recorded scores. I also confirm that answers.json has 50 entries. Fourth, I read spe/evals/harness/r03-workflow.js. I confirm that its runner command and config paths match the defaults below. I copy its measured per-call costs into the `est*` args. The script refuses to start if those args are missing or if the projected spend is over $40. Fifth, I commit spe/evals/harness/r04-workflow.js locally as this step's commit and do not push. That ties the run to a commit hash. Sixth, I do a smoke run with `ticketLimit: 1, trials: 1, outDir: 'spe/evals/runs/r04-smoke'`. I pass the smoke cost into the full run as `spentBeforeUsd`, so the smoke run counts against the same $40.

Some file details were not given, so I assumed that round 3's layout carries over. That means `node spe/evals/harness/run-trial.js`, `spe/evals/configs/B.json` and `spe/evals/configs/C2.json`, and a grade.py that takes `--answers` and `--runs` and prints JSON. All of these are args, so gate four can fix them.

**spe/evals/harness/r04-workflow.js**

```js
export const meta = {
  name: 'spe-r04-eval',
  description: 'SPE round 4. Configs B and C2 on 50 tickets with 5 trials per cell. Code grader checks label.category and label.priority. A blind Opus judge scores reply tone. Spend cap is $40.',
  phases: [
    { title: 'Preflight' },
    { title: 'Trials' },
    { title: 'Grade and judge' },
    { title: 'Report' },
  ],
};

const A = (typeof args !== 'undefined' && args && typeof args === 'object') ? args : {};
const MODEL = 'opus';

const PLAN = {
  round: 'r04',
  configs: {
    B: A.configB ?? 'spe/evals/configs/B.json',
    C2: A.configC2 ?? 'spe/evals/configs/C2.json',
  },
  ticketCount: 50,
  trials: A.trials ?? 5,
  capUsd: 40,
  spentBeforeUsd: A.spentBeforeUsd ?? 0,
  answers: 'spe/evals/tasks/answers.json',
  grader: 'spe/evals/graders/grade.py',
  judgeRubric: 'spe/evals/graders/judge.md',
  runner: A.runner ?? 'node spe/evals/harness/run-trial.js',
  outDir: A.outDir ?? 'spe/evals/runs/r04',
  judgeBatch: A.judgeBatch ?? 10,
  driverConcurrency: A.driverConcurrency ?? 10,
  judgeConcurrency: A.judgeConcurrency ?? 5,
  ticketLimit: A.ticketLimit ?? null,
  seed: A.seed ?? 404,
};
PLAN.gradeCmd = A.gradeCmd ??
  `python3 ${PLAN.grader} --answers ${PLAN.answers} --runs ${PLAN.outDir}/raw --json`;

const IS_SMOKE = PLAN.ticketLimit !== null || PLAN.trials !== 5;
if (IS_SMOKE && PLAN.outDir === 'spe/evals/runs/r04') {
  throw new Error('Smoke runs must write to a different outDir, for example spe/evals/runs/r04-smoke.');
}

// Cost estimates come from round 3 actuals. The script will not guess them.
const EST = {
  estDriverUsd: A.estDriverUsd,          // Opus driver agent overhead per ticket
  estRunUsd: A.estRunUsd,                // one runner call of the config under test
  estJudgeBatchUsd: A.estJudgeBatchUsd,  // one Opus judge call over judgeBatch replies
  estFixedUsd: A.estFixedUsd,            // preflight + grader + report agents together
};
for (const [k, v] of Object.entries(EST)) {
  if (typeof v !== 'number' || !(v > 0)) {
    throw new Error(`Missing args.${k}. Pass the measured per-call cost from round 3.`);
  }
}

// ---------- helpers ----------
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function shuffle(arr, rand) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const tmp = a[i]; a[i] = a[j]; a[j] = tmp;
  }
  return a;
}
function chunk(arr, n) {
  const out = [];
  for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n));
  return out;
}
function rate(n, d) { return d ? Number((n / d).toFixed(4)) : null; }
function mean(xs) { return xs.length ? Number((xs.reduce((s, x) => s + x, 0) / xs.length).toFixed(3)) : null; }
async function tryAgent(prompt, opts) {
  try {
    return await agent(prompt, { model: MODEL, ...opts });
  } catch (e) {
    log(`Agent "${opts.label}" failed: ${e && e.message ? e.message : String(e)}`);
    return null;
  }
}

// ---------- schemas ----------
const PRE_SCHEMA = {
  type: 'object',
  properties: {
    head_sha: { type: 'string' },
    dirty_paths: { type: 'array', items: { type: 'string' } },
    prereg_committed: { type: 'boolean' },
    ticket_ids: { type: 'array', items: { type: 'string' } },
    missing_files: { type: 'array', items: { type: 'string' } },
    out_dir_exists: { type: 'boolean' },
  },
  required: ['head_sha', 'dirty_paths', 'prereg_committed', 'ticket_ids', 'missing_files', 'out_dir_exists'],
};
const DRIVER_SCHEMA = {
  type: 'object',
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          ok: { type: 'boolean' },
          reply: { type: 'string' },
          cost_usd: { type: 'number' },
          error: { type: 'string' },
        },
        required: ['id', 'ok'],
      },
    },
  },
  required: ['results'],
};
const GRADE_SCHEMA = {
  type: 'object',
  properties: {
    rows: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          ticket_id: { type: 'string' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
        },
        required: ['id', 'ticket_id', 'category_ok', 'priority_ok'],
      },
    },
    error: { type: 'string' },
  },
  required: ['rows'],
};
const JUDGE_SCHEMA = {
  type: 'object',
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          score: { type: 'integer' },
          rationale: { type: 'string' },
        },
        required: ['id', 'score'],
      },
    },
  },
  required: ['scores'],
};
const REPORT_SCHEMA = {
  type: 'object',
  properties: { written: { type: 'array', items: { type: 'string' } } },
  required: ['written'],
};

// ---------- Preflight ----------
phase('Preflight');
const configNames = Object.keys(PLAN.configs);
const runnerFile = PLAN.runner.split(/\s+/).find(p => /\.(js|mjs|py)$/.test(p)) ?? '';
const mustExist = [...Object.values(PLAN.configs), PLAN.answers, PLAN.grader, PLAN.judgeRubric, runnerFile].filter(Boolean);

const pre = await tryAgent(
`Read-only preflight for SPE round 4. Do not create, edit, or delete any file. Do not commit.
1. Run \`git rev-parse HEAD\`. Report the hash as head_sha.
2. Run \`git status --porcelain -- spe/\`. Report each output line as dirty_paths.
3. Run \`git log -n1 --format=%H -- spe/predictions/r04.yaml spe/plans/r04.md\`. Set prereg_committed to true only if it prints a hash and neither file appears in step 2.
4. Read ${PLAN.answers}. Report every ticket id in file order as ticket_ids. Use the keys or the id field, whichever the file uses. Do not report the answers.
5. Check that each of these paths exists. List any missing path in missing_files: ${mustExist.join(', ')}
6. Report whether ${PLAN.outDir} exists as out_dir_exists.`,
  { label: 'preflight', phase: 'Preflight', schema: PRE_SCHEMA },
);

const problems = [];
if (!pre) {
  problems.push('preflight agent returned nothing');
} else {
  const dirty = pre.dirty_paths.filter(p => !p.includes('spe/evals/runs/'));
  if (!pre.prereg_committed) problems.push('spe/predictions/r04.yaml and spe/plans/r04.md are not committed');
  if (dirty.length) problems.push(`spe/ has uncommitted changes: ${dirty.join(', ')}`);
  if (pre.missing_files.length) problems.push(`missing files: ${pre.missing_files.join(', ')}`);
  if (pre.out_dir_exists) problems.push(`${PLAN.outDir} already exists. Round 4 must start from an empty run directory.`);
  if (!IS_SMOKE && pre.ticket_ids.length !== PLAN.ticketCount) {
    problems.push(`expected ${PLAN.ticketCount} tickets, found ${pre.ticket_ids.length}`);
  }
  if (new Set(pre.ticket_ids).size !== pre.ticket_ids.length) problems.push('answers.json has duplicate ticket ids');
}
if (problems.length) {
  log(`Preflight failed:\n- ${problems.join('\n- ')}`);
  throw new Error(`Preflight failed: ${problems.join(' | ')}`);
}

const tickets = PLAN.ticketLimit ? pre.ticket_ids.slice(0, PLAN.ticketLimit) : pre.ticket_ids;

// Every run gets an opaque id from a seeded shuffle. The judge sees only these ids.
const allRuns = [];
for (const ticket of tickets) {
  for (const config of configNames) {
    for (let trial = 1; trial <= PLAN.trials; trial++) allRuns.push({ ticket, config, trial });
  }
}
const shuffled = shuffle(allRuns, mulberry32(PLAN.seed));
shuffled.forEach((r, i) => { r.id = `run-${String(i + 1).padStart(3, '0')}`; });
const byId = new Map(shuffled.map(r => [r.id, r]));
const runsByTicket = new Map(tickets.map(t => [t, []]));
for (const r of shuffled) runsByTicket.get(r.ticket).push(r);

const runsPerDriver = configNames.length * PLAN.trials;
const judgeBatches = Math.ceil(shuffled.length / PLAN.judgeBatch);
const projTrials = tickets.length * (EST.estDriverUsd + runsPerDriver * EST.estRunUsd);
const reserve = judgeBatches * EST.estJudgeBatchUsd + EST.estFixedUsd;
const projected = PLAN.spentBeforeUsd + projTrials + reserve;
log(`Plan: ${tickets.length} tickets x ${configNames.length} configs x ${PLAN.trials} trials = ${shuffled.length} runs. Projected spend $${projected.toFixed(2)} of $${PLAN.capUsd}. HEAD ${pre.head_sha}.${IS_SMOKE ? ' SMOKE RUN.' : ''}`);
if (projected > PLAN.capUsd) {
  throw new Error(`Projected spend $${projected.toFixed(2)} is over the $${PLAN.capUsd} cap. Not launching.`);
}

// ---------- Trials ----------
phase('Trials');
function driverPrompt(ticket, runs) {
  const lines = runs.map(r => `- id ${r.id}: --config ${PLAN.configs[r.config]}`).join('\n');
  return `You are a test driver for SPE round 4. You run a fixed command and report what it wrote. You do not judge, fix, or rewrite any answer.

First run \`mkdir -p ${PLAN.outDir}/raw\`.
Then, for ticket ${ticket}, run each line below in this order, one at a time:
  ${PLAN.runner} --config <config> --ticket ${ticket} --out ${PLAN.outDir}/raw/<id>.json
${lines}

After each run, read its output file. Report the id, ok=true, the reply text exactly as written, and usage cost_usd if the file has it.
If a command exits non-zero, retry once only for a rate limit or network error. If it still fails, report ok=false and the first 300 characters of stderr as error, then continue.
Do not edit any file except the --out files the runner writes. Do not open ${PLAN.answers} or anything under spe/evals/graders/, spe/predictions/, or spe/plans/.`;
}

const results = new Map();
let spent = PLAN.spentBeforeUsd;
let stoppedForCap = false;
let ticketsDone = 0;

// Each driver covers both configs for one ticket. A cap stop leaves B and C2 balanced.
for (const group of chunk(tickets, PLAN.driverConcurrency)) {
  const groupProj = group.length * (EST.estDriverUsd + runsPerDriver * EST.estRunUsd);
  if (spent + groupProj + reserve > PLAN.capUsd) {
    stoppedForCap = true;
    log(`Cap stop: $${spent.toFixed(2)} spent. The next group needs about $${groupProj.toFixed(2)}, and $${reserve.toFixed(2)} is reserved for grading and judging. Stopping trials after ${ticketsDone} tickets.`);
    break;
  }
  const out = await parallel(group.map(ticket => () =>
    tryAgent(driverPrompt(ticket, runsByTicket.get(ticket)), {
      label: `trials ${ticket}`, phase: 'Trials', schema: DRIVER_SCHEMA,
    })));
  group.forEach((ticket, i) => {
    spent += EST.estDriverUsd;
    const got = new Map(((out[i] && out[i].results) || []).filter(x => byId.has(x.id)).map(x => [x.id, x]));
    for (const r of runsByTicket.get(ticket)) {
      const x = got.get(r.id);
      if (!x) {
        spent += EST.estRunUsd;
        results.set(r.id, { ok: false, reply: '', cost_usd: null, error: 'driver did not report this run' });
        continue;
      }
      const cost = (typeof x.cost_usd === 'number' && x.cost_usd >= 0) ? x.cost_usd : EST.estRunUsd;
      spent += cost;
      results.set(r.id, {
        ok: Boolean(x.ok) && typeof x.reply === 'string' && x.reply.length > 0,
        reply: x.reply ?? '',
        cost_usd: cost,
        error: x.error ?? '',
      });
    }
  });
  ticketsDone += group.length;
  log(`Trials: ${ticketsDone}/${tickets.length} tickets done. Spend about $${spent.toFixed(2)}.`);
}

// ---------- Grade and judge ----------
phase('Grade and judge');
const okRuns = shuffled.filter(r => results.get(r.id) && results.get(r.id).ok);
log(`${okRuns.length} of ${results.size} attempted runs produced a reply.`);

const gradeTask = () => tryAgent(
`You run the SPE round 4 code grader. You do not grade anything yourself.
Run exactly: ${PLAN.gradeCmd}
The run outputs are the files in ${PLAN.outDir}/raw/. Each file name without .json is the run id.
Return one row per run id, with ticket_id, category_ok, and priority_ok copied from the grader output.
If the command fails, or its output does not give both checks for each run, return an empty rows list and put the error text in error.
Do not edit ${PLAN.grader}, ${PLAN.answers}, or any run file.`,
  { label: 'code grader', phase: 'Grade and judge', schema: GRADE_SCHEMA },
);

function judgePrompt(batch) {
  const blocks = batch.map(r =>
    `<reply id="${r.id}" ticket="${r.ticket}">\n${results.get(r.id).reply}\n</reply>`).join('\n\n');
  return `You are the tone judge for SPE round 4. Read ${PLAN.judgeRubric} and apply it exactly as written.
Score each reply on its own. Do not compare replies with each other.
You do not know which configuration wrote any reply. Do not try to find out.
Do not open anything under spe/evals/runs/, spe/evals/harness/, spe/evals/configs/, spe/predictions/, or spe/plans/.
If you need a ticket's text, open it by ticket id under spe/evals/tasks/ only.
Return one integer score per reply id, on the scale judge.md defines, with a one-sentence rationale.

${blocks}`;
}

const judgeTask = async () => {
  const scores = new Map();
  for (const group of chunk(chunk(okRuns, PLAN.judgeBatch), PLAN.judgeConcurrency)) {
    const groupCost = group.length * EST.estJudgeBatchUsd;
    if (spent + groupCost > PLAN.capUsd) {
      stoppedForCap = true;
      log(`Cap stop during judging at about $${spent.toFixed(2)}. ${scores.size} replies judged.`);
      break;
    }
    spent += groupCost;
    const out = await parallel(group.map((batch, i) => () =>
      tryAgent(judgePrompt(batch), { label: `tone judge ${scores.size + i * PLAN.judgeBatch}`, phase: 'Grade and judge', schema: JUDGE_SCHEMA })));
    group.forEach((batch, i) => {
      const want = new Set(batch.map(r => r.id));
      for (const s of ((out[i] && out[i].scores) || [])) {
        if (want.has(s.id) && Number.isInteger(s.score)) scores.set(s.id, { score: s.score, rationale: s.rationale ?? '' });
      }
    });
  }
  return scores;
};

const [grade, judged] = await parallel([gradeTask, judgeTask]);

const gradeById = new Map();
let ticketMismatch = 0;
for (const row of ((grade && grade.rows) || [])) {
  const r = byId.get(row.id);
  if (!r) continue;
  if (String(row.ticket_id) !== String(r.ticket)) { ticketMismatch++; continue; }
  gradeById.set(row.id, row);
}
if (!grade || (grade.error && grade.error.length)) log(`Grader problem: ${grade ? grade.error : 'no response'}`);
if (ticketMismatch) log(`Grader rows with a ticket id that does not match the run key: ${ticketMismatch}. These rows were dropped.`);

// ---------- Aggregate ----------
const summary = {
  round: PLAN.round,
  smoke: IS_SMOKE,
  head_sha: pre.head_sha,
  seed: PLAN.seed,
  cap_usd: PLAN.capUsd,
  spend_estimate_usd: Number(spent.toFixed(2)),
  stopped_for_cap: stoppedForCap,
  tickets_planned: tickets.length,
  tickets_run: ticketsDone,
  grader_error: grade ? (grade.error ?? '') : 'no response',
  configs: {},
};

for (const c of configNames) {
  const cr = shuffled.filter(r => r.config === c);
  const attempted = cr.filter(r => results.has(r.id));
  const ok = attempted.filter(r => results.get(r.id).ok);
  const graded = ok.filter(r => gradeById.has(r.id));
  const g = r => gradeById.get(r.id);
  const cat = graded.filter(r => g(r).category_ok).length;
  const pri = graded.filter(r => g(r).priority_ok).length;
  const both = graded.filter(r => g(r).category_ok && g(r).priority_ok).length;

  let ticketsComplete = 0;
  let ticketsAllPass = 0;
  for (const t of tickets) {
    const tr = cr.filter(r => r.ticket === t);
    if (tr.length && tr.every(r => gradeById.has(r.id))) {
      ticketsComplete++;
      if (tr.every(r => g(r).category_ok && g(r).priority_ok)) ticketsAllPass++;
    }
  }
  const tones = ok.map(r => judged.get(r.id)).filter(Boolean).map(s => s.score);

  summary.configs[c] = {
    runs_attempted: attempted.length,
    runs_failed: attempted.length - ok.length,
    runs_graded: graded.length,
    category_acc: rate(cat, graded.length),
    priority_acc: rate(pri, graded.length),
    both_correct_acc: rate(both, graded.length),
    both_correct_rate_failures_as_wrong: rate(both, attempted.length),
    tickets_complete: ticketsComplete,
    pass_all_trials_rate: rate(ticketsAllPass, ticketsComplete),
    tone_judged: tones.length,
    tone_mean: mean(tones),
  };
}

for (const [c, s] of Object.entries(summary.configs)) {
  log(`${c}: both-correct ${s.both_correct_acc} over ${s.runs_graded} graded runs, category ${s.category_acc}, priority ${s.priority_acc}, all ${PLAN.trials} trials pass on ${s.pass_all_trials_rate} of ${s.tickets_complete} tickets, tone mean ${s.tone_mean} over ${s.tone_judged}, failed runs ${s.runs_failed}.`);
}

// ---------- Report ----------
phase('Report');
const key = shuffled.map(r => ({
  id: r.id,
  config: r.config,
  ticket: r.ticket,
  trial: r.trial,
  ok: results.has(r.id) ? results.get(r.id).ok : null,
  error: results.has(r.id) ? results.get(r.id).error : 'not run',
  cost_usd: results.has(r.id) ? results.get(r.id).cost_usd : null,
  category_ok: gradeById.has(r.id) ? gradeById.get(r.id).category_ok : null,
  priority_ok: gradeById.has(r.id) ? gradeById.get(r.id).priority_ok : null,
  tone: judged.has(r.id) ? judged.get(r.id).score : null,
  tone_rationale: judged.has(r.id) ? judged.get(r.id).rationale : null,
}));

const report = await tryAgent(
`Write exactly two files and nothing else. Do not edit any other file. Do not commit.
Do not touch spe/prediction-log.md, spe/failures.md, or spe/predictions/. Scoring against r04.yaml is the next SPE step.

File 1: ${PLAN.outDir}/summary.json
${JSON.stringify(summary, null, 2)}

File 2: ${PLAN.outDir}/key.json
${JSON.stringify(key, null, 2)}

Write each file's JSON exactly as given. Report the paths you wrote.`,
  { label: 'write results', phase: 'Report', schema: REPORT_SCHEMA },
);
if (!report) log(`Results were not written. The summary is in this script's return value.`);

log(`Done. Spend about $${spent.toFixed(2)} of $${PLAN.capUsd}.${stoppedForCap ? ' The cap stopped the run early.' : ''}`);
return summary;
```
